content.thinking:
Chrome found. Now create the evidence scenario page and take screenshots. First, an initial screenshot via file:// to prove static open, then the behavioral scenario via http (need python or node — node exists since prax uses it). Node static server: use `npx http-server`? Might download. Simpler: write a tiny node server script (evidence/serve.js) and run in background.

Actually — for the behavioral scenario I can avoid fetch/http entirely: build scenario.html that inlines the body markup? No — better idea: scenario.html uses document.write to load index.html content synchronously via XHR — blocked on file://. 

Alternative without server: scenario.html = <iframe src="index.html"> and drive via postMessage? Cross-origin on file:// blocks even postMessage? postMessage works cross-origin (explicitly designed for it, targetOrigin '*'). The app itself doesn't listen for messages though. I can't inject script into the iframe from parent on file:// (unique origin blocks contentWindow access... actually file:// iframes: Chrome treats each file as opaque origin; contentDocument access blocked, but window.postMessage IS allowed).

But nothing in the app listens to messages. I could add a tiny message listener in app.js? That pollutes production code. Small addition, harmless, but no.

Simplest: node one-liner static server (node is guaranteed — prax runs on node). Write evidence/serve.js: static file server on 8123. Run hidden in background via PowerShell Start-Process. Then everything (screenshots, scenario) runs over http://127.0.0.1:8123/, AND separately screenshot file:// for the static-open requirement.

Serve.js:
```js
const http=require('http'),fs=require('fs'),path=require('path');
const root=__dirname+'/..';
http.createServer((req,res)=>{
  let p=decodeURIComponent(req.url.split('?')[0]); if(p==='/')p='/index.html';
  const f=path.join(root,p);
  fs.readFile(f,(e,d)=>{ if(e){res.writeHead(404);res.end('nf');return;}
    const ext=path.extname(f);
    const mime={'.html':'text/html; charset=utf-8','.js':'text/javascript; charset=utf-8','.css':'text/css; charset=utf-8','.json':'application/json'}[ext]||'application/octet-stream';
    res.writeHead(200,{'Content-Type':mime});res.end(d);});
}).listen(8123,'127.0.0.1',()=>console.log('up'));
```

scenario.html plan (served at /evidence/scenario.html): it must render the app AND run assertions. Structure: fetch('/index.html') → parse → take body innerHTML into this page, then load /data.js and /app.js via dynamic script injection with await; app.js IIFE executes rendering into #app of THIS document. Then run scenario via window.__prism, appending PASS/FAIL lines to #evidence-log (position:fixed bottom, semi-transparent? For behavior screenshot visibility keep visible but small). Screenshot with virtual-time-budget so scripts settle.

Wait — app.js IIFE has its own closure; __prism exposed on window — good. measure etc fine.

Careful: app.js references document.getElementById('app') etc. — our page will have identical structure after injecting index.html's body content. Also index.html includes <script src="app.js"> tags at body end — if I set document.body.innerHTML from index.html body, those script tags won't execute (innerHTML scripts don't run). So I inject body HTML minus scripts (strip <script> tags), then create script elements manually in order: data.js → app.js → scenario.

Let me write scenario.html:

```html
<!doctype html><html lang="zh-CN"><head><meta charset="utf-8"><title>scenario</title><link rel="stylesheet" href="/styles.css"></head>
<body class="scenario-page">
<div id="mount"></div>
<pre id="evidence-log"></pre>
<script>
(async function(){
  const log = [];
  const out = document.getElementById('evidence-log');
  function say(s){ log.push(s); out.textContent = log.join('\n'); }
  function assert(name, cond){ say((cond?'PASS':'FAIL') + ' | ' + name); return cond; }
  // 1. load index.html body
  const res = await fetch('/index.html'); const txt = await res.text();
  const doc = new DOMParser().parseFromString(txt, 'text/html');
  document.body.innerHTML = doc.body.innerHTML.replace(/<script[\s\S]*?<\/script>/g,'');
  // 2. load app scripts in order
  await new Promise(r=>{const s=document.createElement('script');s.src='/data.js';s.onload=r;document.head.appendChild(s);});
  await new Promise(r=>{const s=document.createElement('script');s.src='/app.js';s.onload=r;document.head.appendChild(s);});
  const P = window.__prism; const store = P.store;
  const $ = id=>document.getElementById(id);
  // S1 ready
  assert('S1 页面就绪：分布条形已渲染', document.querySelectorAll('#chart .bar-row').length > 0);
  assert('S2 首屏即用：无加载态元素', !document.querySelector('.loading,.spinner,[data-state="loading"]'));
  assert('S3 状态托盘初始 1 条（默认投影，有归属）', P.trayEntries().length===1 && P.trayEntries()[0].kind==='projection');
  const total = P.matched().length;
  assert('S4 全量命中='+total, total===1280);
  // 5. select a record (认知连续性准备)
  const firstRow = document.querySelector('#table-wrap tr[data-rid]');
  const rid = firstRow.getAttribute('data-rid');
  firstRow.click();
  assert('S5 选中记录 '+rid+'（inspector 渲染）', !!document.querySelector('#inspector-body .insp-id'));
  // 6. filter via rail: region=亚太 (valueIdx 0)
  P.toggleFilter('region', 0, '维度轨');
  const hit1 = P.matched().length;
  assert('S6 过滤 区域＝亚太 后命中下降', hit1>0 && hit1<total);
  // tray entry ownership
  const fe = P.trayEntries().find(e=>e.kind==='filter');
  assert('S7 状态条目有归属（dim=region, origin=维度轨）', fe && fe.dim==='region' && fe.origin==='维度轨');
  // 8. switch projection to category — 认知不重置
  P.commit(P.makeSetProjection('category','维度轨'));
  assert('S8 切换投影后过滤器仍在（认知不重置）', store.filters.length===1 && store.filters[0].dim==='region');
  assert('S9 切换投影后选中仍保持', store.selectedId===rid);
  assert('S10 记录表列头换为 产品线', !!document.querySelector('.th-proj') && document.querySelector('.th-proj').textContent.includes('产品线'));
  // 11. orphan filter: now filter channel=直销 while projecting category → region filter becomes orphan
  const fe2 = P.trayEntries().find(e=>e.kind==='filter');
  assert('S11 孤儿过滤器标注「不在当前投影」', document.querySelector('#tray-body .tag-warn') !== null);
  // 12. revert filter via tray ×: click the filter entry's x
  const xbtn = document.querySelector('#tray-body .entry-x[data-act="revert-filter"]');
  xbtn.click();
  assert('S12 托盘 × 单条回退后命中恢复', P.matched().length===total && store.filters.length===0);
  // 13. undo the revert → filter comes back
  P.undo();
  assert('S13 Ctrl+Z 撤销后过滤恢复', store.filters.length===1);
  // 14. undo again → projection back to region
  P.undo();
  assert('S14 再次撤销：投影回到 区域', store.projection.primary==='region');
  // 15. undo again → filter removed (undo the original add)
  P.undo();
  assert('S15 撤销最初加的过滤：query 干净', store.filters.length===0);
  // 16. re-add filter + breakdown + reset all
  P.toggleFilter('quarter', 4, '分布图');
  P.commit(P.makeSetBreakdown('channel','细分下拉'));
  P.commit(P.makeResetAll('头部重置'));
  assert('S16 全部重置：投影回默认、过滤清空、细分移除', store.projection.primary==='region' && store.projection.breakdown===null && store.filters.length===0);
  // 17. redo stack availability
  assert('S17 撤销栈可用（重置可撤销）', store.undoStack.length>0 && document.getElementById('btn-undo').disabled===false);
  // final visual state: re-apply filter+projection switch for the "state after interaction" screenshot
  P.toggleFilter('segment', 3, '维度轨');         // 大型企业
  P.commit(P.makeSetProjection('category','维度轨')); // 投影 → 产品线（segment 成为孤儿过滤器）
  document.getElementById('btn-undo').focus && null;
  say('SCENARIO-DONE');
})();
</script>
</body></html>
```

