7	  /* mulberry32 —— 种子确定性 PRNG，保证每次打开数据一致 */
8	  function mulberry32(seed) {
9	    var a = seed | 0;
10	    return function () {
11	      a = (a + 0x6D2B79F5) | 0;
12	      var t = Math.imul(a ^ (a >>> 15), 1 | a);
13	      t = (t + Math.imul(t ^ (t >>> 7), 61 | t)) ^ t;
14	      return ((t ^ (t >>> 14)) >>> 0) / 4294967296;
15	    };
16	  }
17	
18	  var rnd = mulberry32(20260908);
19	
20	  function weighted(pairs) { // [[value, weight], ...]
21	    var total = 0, i;
22	    for (i = 0; i < pairs.length; i++) total += pairs[i][1];
23	    var r = rnd() * total;
24	    for (i = 0; i < pairs.length; i++) {
25	      r -= pairs[i][1];
26	      if (r <= 0) return pairs[i][0];
27	    }
28	    return pairs[pairs.length - 1][0];
29	  }
