/* ============ Prism 多维探索台 · 结构化密度（H-13）+ Signal over Chrome（P-22） ============ */
:root {
  --bg: #eef0f4;
  --panel: #ffffff;
  --ink: #1b1e2b;
  --ink-2: #4b5060;
  --muted: #858b9b;
  --line: #e0e3ea;
  --line-2: #eceef3;
  --accent: #4f46e5;
  --accent-ink: #3d36c4;
  --accent-soft: #eef0ff;
  --filter: #0e7c66;
  --filter-soft: #e3f5ef;
  --proj: #4f46e5;
  --proj-soft: #eef0ff;
  --warn: #b45309;
  --warn-soft: #fef3e2;
  --danger: #c2372f;
  --mono: "Cascadia Mono", Consolas, "Courier New", monospace;
  --sans: "Segoe UI", "Microsoft YaHei", "PingFang SC", system-ui, sans-serif;
  --radius: 8px;
}

* { box-sizing: border-box; margin: 0; padding: 0; }
html, body { height: 100%; }
body {
  font-family: var(--sans);
  font-size: 12.5px;
  color: var(--ink);
  background: var(--bg);
  line-height: 1.45;
}
button { font: inherit; color: inherit; background: none; border: 0; cursor: pointer; }
button:disabled { cursor: not-allowed; opacity: .45; }
:focus-visible { outline: 2px solid var(--accent); outline-offset: 1px; border-radius: 3px; }

#app { height: 100vh; display: flex; flex-direction: column; overflow: hidden; }

/* ============ app-header ============ */
.app-header {
  display: flex; align-items: center; gap: 20px;
  padding: 0 16px; height: 52px; flex: 0 0 52px;
  background: #191c2e; color: #f2f3f8;
}
.brand { display: flex; align-items: center; gap: 10px; min-width: 0; }
.brand-mark {
  width: 28px; height: 28px; border-radius: 7px; flex: 0 0 28px;
  background: linear-gradient(135deg, #6d64ff, #4038b8);
  color: #fff; font-size: 15px; display: grid; place-items: center;
}
.brand-name { font-size: 13.5px; font-weight: 650; letter-spacing: .2px; }
.brand-sub { font-size: 11px; color: #9aa0b8; }
.brand-sub strong { color: #d6d9ea; font-weight: 600; }
.dot { margin: 0 6px; color: #565c78; }

.header-stats { display: flex; gap: 14px; margin-left: 8px; font-size: 11.5px; color: #9aa0b8; }
.header-stats b { color: #f2f3f8; font-weight: 650; font-variant-numeric: tabular-nums; }
.stat-hit b { color: #8de3c8; }

.header-actions { margin-left: auto; display: flex; gap: 8px; }
.btn {
  padding: 5px 12px; border-radius: 6px; font-size: 12px; font-weight: 550;
  background: #262a44; color: #d6d9ea; border: 1px solid #343957;
  transition: background .12s, border-color .12s;
}
.btn:hover:not(:disabled) { background: #303554; border-color: #434a70; }
.btn-danger-ghost { color: #f0b9b4; border-color: #4b3136; }
.btn-danger-ghost:hover:not(:disabled) { background: #3a2830; border-color: #6b4148; }

/* ============ 工作区布局 ============ */
.workspace {
  flex: 1; min-height: 0;
  display: grid; grid-template-columns: 272px minmax(0, 1fr) 316px;
  gap: 10px; padding: 10px;
}
.panel {
  background: var(--panel); border: 1px solid var(--line);
  border-radius: var(--radius); display: flex; flex-direction: column;
  min-height: 0; overflow: hidden;
}
.panel-hd {
  display: flex; align-items: baseline; gap: 8px;
  padding: 9px 12px 8px; border-bottom: 1px solid var(--line-2); flex: 0 0 auto;
}
.panel-title { font-size: 12px; font-weight: 700; letter-spacing: .4px; text-transform: uppercase; color: var(--ink-2); }
.panel-hint { font-size: 10.5px; color: var(--muted); margin-left: auto; }
.panel-bd { flex: 1; min-height: 0; overflow-y: auto; }
.panel-ft {
  flex: 0 0 auto; padding: 6px 12px; border-top: 1px solid var(--line-2);
  font-size: 10.5px; color: var(--muted);
}
.count-chip {
  display: inline-block; min-width: 18px; text-align: center;
  background: var(--accent-soft); color: var(--accent-ink);
  border-radius: 9px; padding: 0 6px; font-size: 10.5px; font-weight: 700;
}

/* ============ 维度轨（collection） ============ */
.rail-panel .panel-bd { padding: 4px 0 10px; }
.dim { border-bottom: 1px solid var(--line-2); padding: 2px 0; transition: background .15s; }
.dim.flash { background: #f2f4ff; box-shadow: inset 2px 0 0 var(--accent); }
.dim-hd { display: flex; align-items: center; padding: 3px 10px 3px 6px; gap: 2px; }
.dim-exp {
  flex: 0 0 20px; height: 24px; color: var(--muted); border-radius: 4px;
  font-size: 10px; display: grid; place-items: center;
}
.dim-exp:hover { background: var(--line-2); color: var(--ink); }
.dim-name {
  display: flex; align-items: center; gap: 6px;
  padding: 4px 7px; border-radius: 5px; font-weight: 600; font-size: 12.5px;
  color: var(--ink); min-width: 0; flex: 0 1 auto;
}
.dim-name:hover { background: var(--line-2); }
.dim-name.is-proj { color: var(--accent-ink); background: var(--proj-soft); }
.dim-icon { color: var(--muted); font-size: 11px; width: 14px; text-align: center; }
.dim-name.is-proj .dim-icon { color: var(--accent); }
.dim-cardinality { font-size: 10px; color: var(--muted); font-weight: 450; margin-left: 2px; white-space: nowrap; }
.dim-role { margin-left: auto; display: flex; gap: 4px; flex: 0 0 auto; }
.chip {
  font-size: 9.5px; font-weight: 650; padding: 1px 6px; border-radius: 8px; white-space: nowrap;
}
.chip-proj { background: var(--proj-soft); color: var(--accent-ink); }
.chip-break { background: #e8f6fb; color: #0b6e86; }
.chip-filter { background: var(--filter-soft); color: var(--filter); }

.dim-vals { padding: 2px 10px 8px 28px; display: flex; flex-direction: column; gap: 1px; }
.dim-val {
  display: grid; grid-template-columns: 13px minmax(0, 1fr) 44px 34px;
  align-items: center; gap: 6px; padding: 2px 4px; border-radius: 4px;
  font-size: 11.5px; cursor: pointer;
}
.dim-val:hover { background: var(--line-2); }
.dim-val.on { background: var(--filter-soft); }
.dim-val.on .dv-name { color: var(--filter); font-weight: 600; }
.dim-val input { accent-color: var(--filter); width: 12px; height: 12px; cursor: pointer; }
.dv-name { overflow: hidden; text-overflow: ellipsis; white-space: nowrap; }
.dv-bar { height: 4px; border-radius: 2px; background: var(--line-2); overflow: hidden; }
.dv-bar i { display: block; height: 100%; background: #b9c0d4; border-radius: 2px; }
.dim-val.on .dv-bar i { background: var(--filter); }
.dv-count { text-align: right; color: var(--muted); font-variant-numeric: tabular-nums; font-size: 10.5px; }

/* ============ 投影工作面（data） ============ */
.center-bd { display: flex; flex-direction: column; }
.projection-hd { align-items: center; }
.proj-title { display: flex; align-items: baseline; gap: 8px; min-width: 0; }
.proj-sub { font-size: 11px; color: var(--muted); overflow: hidden; text-overflow: ellipsis; white-space: nowrap; }
.proj-controls { margin-left: auto; display: flex; gap: 10px; flex: 0 0 auto; }
.ctl { font-size: 10.5px; color: var(--muted); display: flex; align-items: center; gap: 5px; }
.ctl select {
  font: inherit; font-size: 11.5px; color: var(--ink);
  border: 1px solid var(--line); border-radius: 5px; padding: 2px 6px; background: #fbfbfd;
}

.chart-block, .table-block { padding: 8px 14px 4px; }
.chart-block { flex: 0 0 auto; }
.table-block { flex: 1; min-height: 0; display: flex; flex-direction: column; padding-bottom: 10px; }
.block-hd { display: flex; align-items: baseline; gap: 10px; margin-bottom: 6px; }
.block-hd h3 { font-size: 11px; font-weight: 700; color: var(--ink-2); letter-spacing: .3px; }
.block-hint { font-size: 10.5px; color: var(--muted); }

#chart { display: flex; flex-direction: column; gap: 3px; position: relative; }
.bar-row {
  display: grid; grid-template-columns: 96px minmax(0, 1fr) 76px 52px;
  align-items: center; gap: 10px; padding: 2px 6px; border-radius: 5px;
  text-align: left;
}
.bar-row:hover { background: var(--line-2); }
.bar-row.active { background: var(--accent-soft); box-shadow: inset 0 0 0 1px #c3c0f5; }
.bar-row.zero .bar-label, .bar-row.zero .bar-value { color: var(--muted); }
.bar-label { font-size: 11.5px; font-weight: 550; overflow: hidden; text-overflow: ellipsis; white-space: nowrap; }
.bar-row.active .bar-label { color: var(--accent-ink); }
.bar-track { height: 16px; position: relative; }
.bar {
  position: absolute; inset: 0 auto 0 0; border-radius: 3px;
  background: linear-gradient(90deg, #6a63f0, #4f46e5); min-width: 0;
  transition: width .18s ease;
}
.bar-stack { display: flex; overflow: hidden; border-radius: 3px; }
.bar-stack .seg { display: block; height: 100%; }
.bar-value { text-align: right; font-variant-numeric: tabular-nums; font-size: 11.5px; font-weight: 600; }
.bar-count { text-align: right; color: var(--muted); font-size: 10.5px; font-variant-numeric: tabular-nums; }
#chart.all-zero::after {
  content: "所有取值均为 0 —— 调整或回退其他维度的过滤";
  position: absolute; inset: 0; display: grid; place-items: center;
  font-size: 11.5px; color: var(--muted); background: rgba(255,255,255,.75);
}

.legend { margin-top: 7px; font-size: 10.5px; color: var(--ink-2); display: flex; flex-wrap: wrap; gap: 4px 10px; align-items: center; }
.lg-title { color: var(--muted); }
.lg-item { display: inline-flex; align-items: center; gap: 4px; }
.lg-item i { width: 9px; height: 9px; border-radius: 2px; display: inline-block; }

/* 记录表 */
.table-wrap { flex: 1; min-height: 0; overflow: auto; border: 1px solid var(--line-2); border-radius: 6px; }
.table-wrap table { width: 100%; border-collapse: collapse; font-size: 11.5px; }
.table-wrap thead th {
  position: sticky; top: 0; z-index: 1;
  background: #f7f8fb; color: var(--ink-2); font-weight: 650;
  text-align: left; padding: 5px 10px; border-bottom: 1px solid var(--line);
  white-space: nowrap;
}
.th-num { text-align: right !important; }
.th-sort { font: inherit; color: inherit; font-weight: 650; padding: 1px 4px; border-radius: 4px; }
.th-sort:hover { background: var(--line-2); color: var(--ink); }
.th-proj { color: var(--accent-ink) !important; }
.td-id { font-family: var(--mono); font-size: 10.5px; color: var(--muted); white-space: nowrap; }
.td-dim { font-weight: 550; white-space: nowrap; }
.td-num { text-align: right; font-variant-numeric: tabular-nums; white-space: nowrap; }
.table-wrap tbody tr { cursor: pointer; border-bottom: 1px solid var(--line-2); }
.table-wrap tbody tr:hover { background: #f6f7fd; }
.table-wrap tbody tr.sel { background: var(--accent-soft); box-shadow: inset 2px 0 0 var(--accent); }
.table-wrap tbody tr.sel .td-id { color: var(--accent-ink); }

.empty-state {
  padding: 42px 20px; text-align: center; color: var(--muted); font-size: 12px;
  display: flex; flex-direction: column; gap: 12px; align-items: center;
}
.empty-icon { font-size: 26px; color: #c3c8d6; }
.empty-state .btn { background: var(--panel); color: var(--ink); border: 1px solid var(--line); }
.empty-state .btn:hover { background: var(--line-2); }

/* ============ 右列：状态托盘 + 明细 ============ */
.right-col { display: flex; flex-direction: column; gap: 10px; min-height: 0; }
.tray-panel { flex: 0 1 auto; max-height: 52%; }
.inspector-panel { flex: 1 1 auto; }

.tray-body { padding: 6px 8px; display: flex; flex-direction: column; gap: 5px; }
.tray-empty { padding: 18px 10px; text-align: center; color: var(--muted); font-size: 11px; line-height: 1.7; }
.state-entry {
  display: flex; align-items: flex-start; gap: 7px;
  border: 1px solid var(--line); border-radius: 6px; padding: 6px 6px 6px 8px;
  background: #fdfdfe;
}
.state-entry.kind-projection { background: #fbfbff; border-color: #dcdaf7; }
.badge {
  flex: 0 0 auto; font-size: 9.5px; font-weight: 700; padding: 2px 6px;
  border-radius: 4px; margin-top: 1px; letter-spacing: .5px;
}
.badge-filter { background: var(--filter-soft); color: var(--filter); }
.badge-proj { background: var(--proj-soft); color: var(--accent-ink); }
.entry-main { min-width: 0; flex: 1; }
.entry-title { font-size: 11.5px; }
.entry-title b { font-weight: 650; }
.entry-meta { display: flex; flex-wrap: wrap; gap: 3px 8px; margin-top: 2px; font-size: 10px; color: var(--muted); }
.origin { color: var(--muted); }
.tag { font-size: 9.5px; padding: 0 5px; border-radius: 3px; font-weight: 600; }
.tag-warn { background: var(--warn-soft); color: var(--warn); }
.entry-x {
  flex: 0 0 auto; width: 20px; height: 20px; border-radius: 4px;
  color: var(--muted); font-size: 10.5px; display: grid; place-items: center;
}
.entry-x:hover:not(:disabled) { background: #fbe9e7; color: var(--danger); }

/* ============ 明细（detail / contextual inspector） ============ */
.inspector-panel .panel-bd { padding: 10px 12px; }
.insp-empty { color: var(--muted); font-size: 11.5px; text-align: center; padding: 26px 8px; line-height: 1.8; }
.insp-hint { font-size: 10.5px; color: #a7acbc; }
.insp-warn {
  background: var(--warn-soft); color: var(--warn);
  border-radius: 6px; padding: 6px 9px; font-size: 11px; margin-bottom: 9px; font-weight: 550;
}
.insp-id { font-family: var(--mono); font-size: 11px; color: var(--ink-2); margin-bottom: 8px; }
.kv-grid { display: flex; flex-direction: column; }
.kv {
  display: grid; grid-template-columns: 64px minmax(0, 1fr) auto;
  align-items: center; gap: 8px; padding: 4.5px 2px;
  border-bottom: 1px solid var(--line-2); font-size: 11.5px;
}
.kv-k { color: var(--muted); font-size: 10.5px; }
.kv-v { font-weight: 600; overflow: hidden; text-overflow: ellipsis; white-space: nowrap; }
.kv-measure .kv-v { font-variant-numeric: tabular-nums; }
.kv-act {
  font-size: 10px; font-weight: 600; color: var(--filter);
  background: var(--filter-soft); border-radius: 4px; padding: 1.5px 7px;
}
.kv-act:hover { background: #d2eee5; }

/* ============ 错误态 ============ */
.app-error { padding: 60px 40px; text-align: center; color: var(--danger); }
.app-error h2 { font-size: 16px; margin-bottom: 8px; }

/* 滚动条（webkit，窄而安静） */
::-webkit-scrollbar { width: 9px; height: 9px; }
::-webkit-scrollbar-thumb { background: #cdd2df; border-radius: 5px; border: 2px solid var(--panel); }
::-webkit-scrollbar-thumb:hover { background: #b6bdcd; }

