1	/* ============ Prism 多维探索台 ============
2	 * 状态架构（对应 design_decisions MC-1/MC-2）：
3	 *  - query 层（过滤 + 投影）是唯一事实源，过滤按维度归属、与投影正交；
4	 *    切换投影永不触碰过滤器（维度切换不重置认知）。
5	 *  - 每次过滤/投影变更 = 一条带 id 的状态条目（kind / dim / origin），
6	 *    托盘逐条可见、逐条可回退；另有撤销栈（Ctrl+Z）与全部重置。
7	 *  - selection 层由记录表拥有，跨投影保持（H-21 Orientation Invariants）。
8	 */
9	(function () {
10	  'use strict';
11	
12	  var DS = window.PRISM_DATASET;
13	  var DIMS = DS.dimensions;
14	  var RECORDS = DS.records;
15	  var MEASURES = DS.measures;
16	  var dimById = {};
17	  DIMS.forEach(function (d) { dimById[d.id] = d; });
18	  var DEFAULT_PROJECTION = { primary: 'region', breakdown: null };
19	  var PALETTE = ['#4F6BED', '#E4572E', '#2CA58D', '#B27CDA', '#D9A404', '#3AA6B9', '#D46A9C', '#7A8B99'];
20	  var TABLE_CAP = 60;
21	
22	  /* ---------- query store ---------- */
23	  var store = {
24	    filters: [],                       // [{id, dim, valueIdx, origin, at}]
25	    projection: { primary: 'region', breakdown: null },
26	    projOrigin: '初始默认',            // 当前投影的来源（归属）
27	    breakdownOrigin: null,
28	    projHistory: [],                   // [{primary, breakdown}] —— 投影条目 × 的回退目标
29	    selectedId: null,                  // selection：跨投影保持
30	    sort: { key: 'revenue', dir: -1 }, // 视图偏好（非 query，不入撤销栈）
31	    measure: 'revenue',
32	    expanded: { region: true },
33	    undoStack: [], redoStack: []
34	  };
35	
36	  var _uid = 1;
37	  function uid() { return 'st-' + (_uid++); }
38	  function dimIdx(rec, dim) { return dim.kind === 'numeric' ? rec._revBin : rec[dim.id]; }
39	  function dimVal(rec, dim) { return dim.values[dimIdx(rec, dim)]; }
40	
41	  /* ---------- 聚合与过滤 ---------- */
42	  function filterGroups(excludeDim) {
43	    var g = {};
44	    store.filters.forEach(function (f) {
45	      if (f.dim === excludeDim) return;
46	      (g[f.dim] = g[f.dim] || []).push(f.valueIdx);
47	    });
48	    return g;
49	  }
50	  function passFilters(rec, groups) {
51	    for (var dimId in groups) {
52	      if (groups[dimId].indexOf(dimIdx(rec, dimById[dimId])) === -1) return false;
53	    }
54	    return true;
55	  }
56	  function matched() {
57	    var g = filterGroups(null), out = [];
58	    for (var i = 0; i < RECORDS.length; i++) if (passFilters(RECORDS[i], g)) out.push(RECORDS[i]);
59	    return out;
60	  }
61	  function aggregate(recs, measureId, excludeDim) {
62	    // 分布图：排除主维度自身的过滤（标准 cross-filter），其余维度过滤计入
63	    var g = filterGroups(excludeDim), sum = 0, n = 0;
64	    for (var i = 0; i < recs.length; i++) {
65	      if (!passFilters(recs[i], g)) continue;
66	      n++;
67	      sum += recs[i][measureId === 'margin' ? 'margin' : measureId];
68	    }
69	    return { value: measureId === 'margin' && n ? sum / n : sum, count: n };
70	  }
71	
72	  /* ---------- 命令式变更（每步可撤销，状态有归属） ---------- */
73	  function commit(op) {
74	    op.do();
75	    store.redoStack.length = 0;
76	    store.undoStack.push(op);
77	    renderAll();
78	  }
79	  function undo() {
80	    var op = store.undoStack.pop();
81	    if (!op) return;
82	    op.undo();
83	    store.redoStack.push(op);
84	    renderAll();
85	  }
86	  function redo() {
87	    var op = store.redoStack.pop();
88	    if (!op) return;
89	    op.do();
90	    store.undoStack.push(op);
91	    renderAll();
92	  }
93	
94	  function makeAddFilter(dimId, valueIdx, origin) {
95	    var exists = store.filters.some(function (f) { return f.dim === dimId && f.valueIdx === valueIdx; });
96	    if (exists) return null;
97	    var entry = { id: uid(), kind: 'filter', dim: dimId, valueIdx: valueIdx, origin: origin, at: Date.now() };
98	    return {
99	      describe: '过滤 ' + dimById[dimId].name + '＝' + dimById[dimId].values[valueIdx],
100	      do: function () { store.filters.push(entry); },
101	      undo: function () { store.filters = store.filters.filter(function (f) { return f.id !== entry.id; }); }
102	    };
103	  }
104	  function makeRemoveFilter(fid) {
105	    var entry = store.filters.filter(function (f) { return f.id === fid; })[0];
106	    if (!entry) return null;
107	    return {
108	      describe: '回退 ' + dimById[entry.dim].name + '＝' + dimById[entry.dim].values[entry.valueIdx],
109	      do: function () { store.filters = store.filters.filter(function (f) { return f.id !== fid; }); },
110	      undo: function () { store.filters.push(entry); }
111	    };
112	  }
113	  function makeSetProjection(dimId, origin) {
114	    var prev = { primary: store.projection.primary, breakdown: store.projection.breakdown, projOrigin: store.projOrigin, breakdownOrigin: store.breakdownOrigin };
115	    var next = { primary: dimId, breakdown: prev.breakdown === dimId ? null : prev.breakdown, projOrigin: origin, breakdownOrigin: prev.breakdown === dimId ? null : prev.breakdownOrigin };
116	    return {
117	      describe: '投影 → ' + dimById[dimId].name,
118	      do: function () {
119	        store.projHistory.push(prev);
120	        if (store.projHistory.length > 30) store.projHistory.shift();
121	        store.projection.primary = next.primary;
122	        store.projection.breakdown = next.breakdown;
123	        store.projOrigin = next.projOrigin;
124	        store.breakdownOrigin = next.breakdownOrigin;
125	        store.expanded[dimId] = true;
126	      },
127	      undo: function () {
128	        store.projHistory.pop();
129	        store.projection.primary = prev.primary;
130	        store.projection.breakdown = prev.breakdown;
131	        store.projOrigin = prev.projOrigin;
132	        store.breakdownOrigin = prev.breakdownOrigin;
133	      }
134	    };
135	  }
136	  function makeSetBreakdown(dimId /* 可为 null */, origin) {
137	    var prev = { breakdown: store.projection.breakdown, breakdownOrigin: store.breakdownOrigin };
138	    return {
139	      describe: dimId ? '细分 → ' + dimById[dimId].name : '移除细分',
140	      do: function () { store.projection.breakdown = dimId; store.breakdownOrigin = origin; },
141	      undo: function () { store.projection.breakdown = prev.breakdown; store.breakdownOrigin = prev.breakdownOrigin; }
142	    };
143	  }
144	  function makeResetAll(origin) {
145	    var snap = {
146	      filters: store.filters.slice(),
147	      projection: { primary: store.projection.primary, breakdown: store.projection.breakdown },
148	      projOrigin: store.projOrigin, breakdownOrigin: store.breakdownOrigin,
149	      projHistory: store.projHistory.slice()
150	    };
151	    return {
152	      describe: '全部重置',
153	      do: function () {
154	        store.filters = [];
155	        store.projection = { primary: DEFAULT_PROJECTION.primary, breakdown: null };
156	        store.projOrigin = origin;
157	        store.breakdownOrigin = null;
158	        store.projHistory = [];
159	      },
160	      undo: function () {
161	        store.filters = snap.filters;
162	        store.projection = snap.projection;
163	        store.projOrigin = snap.projOrigin;
164	        store.breakdownOrigin = snap.breakdownOrigin;
165	        store.projHistory = snap.projHistory;
166	      }
167	    };
168	  }
169	
170	  function toggleFilter(dimId, valueIdx, origin) {
171	    var hit = null;
172	    store.filters.forEach(function (f) { if (f.dim === dimId && f.valueIdx === valueIdx) hit = f; });
173	    if (hit) { var op = makeRemoveFilter(hit.id); op && commit(op); }
174	    else { var op2 = makeAddFilter(dimId, valueIdx, origin); op2 && commit(op2); }
175	  }
176	  function revertProjection() {
177	    var target = store.projHistory[store.projHistory.length - 1] || DEFAULT_PROJECTION;
178	    commit(makeSetProjection(target.primary, '托盘回退'));
179	  }
180	
181	  /* ---------- 格式化 ---------- */
182	  function fmtMoney(v) {
183	    if (Math.abs(v) >= 10000) {
184	      var w = v / 10000;
185	      return '¥' + (w >= 100 ? Math.round(w) : w.toFixed(1)) + '万';
186	    }
187	    return '¥' + Math.round(v).toLocaleString('zh-CN');
188	  }
189	  function fmtMeasure(id, v) {
190	    if (id === 'revenue') return fmtMoney(v);
191	    if (id === 'units') return Math.round(v).toLocaleString('zh-CN');
192	    return v.toFixed(1) + '%';
193	  }
194	
195	  /* ---------- 渲染 ---------- */
196	  var $ = function (id) { return document.getElementById(id); };
197	  var appEl = $('app');
198	  var lastFocusKey = null;
199	
200	  function focusKey(el) {
201	    while (el && el !== appEl) {
202	      if (el.getAttribute && el.getAttribute('data-k')) return el.getAttribute('data-k');
203	      el = el.parentNode;
204	    }
205	    return null;
206	  }
207	
208	  function renderAll() {
209	    var ae = document.activeElement;
210	    lastFocusKey = ae ? focusKey(ae) : null;
211	    renderHeader();
212	    renderRail();
213	    renderProjectionBar();
214	    renderChart();
215	    renderTable();
216	    renderTray();
217	    renderInspector();
218	    if (lastFocusKey) {
219	      var again = appEl.querySelector('[data-k="' + lastFocusKey + '"]');
220	      if (again && again.focus) again.focus({ preventScroll: true });
221	    }
222	  }
223	
224	  function renderHeader() {
225	    var hit = matched().length;
226	    $('ds-name').textContent = DS.name + ' ' + DS.version;
227	    $('header-stats').innerHTML =
228	      '<span class="stat">记录 <b>' + RECORDS.length.toLocaleString('zh-CN') + '</b></span>' +
229	      '<span class="stat">维度 <b>' + DIMS.length + '</b></span>' +
230	      '<span class="stat stat-hit">当前命中 <b>' + hit.toLocaleString('zh-CN') + '</b></span>';
231	    $('btn-undo').disabled = store.undoStack.length === 0;
232	    $('btn-redo').disabled = store.redoStack.length === 0;
233	    var dirty = store.filters.length > 0 ||
234	      store.projection.primary !== DEFAULT_PROJECTION.primary ||
235	      store.projection.breakdown !== null;
236	    $('btn-reset').disabled = !dirty;
237	  }
238	
239	  function renderRail() {
240	    var html = [];
241	    var projected = store.projection.primary;
242	    var breakdown = store.projection.breakdown;
243	    DIMS.forEach(function (dim) {
244	      var open = !!store.expanded[dim.id];
245	      var fCount = store.filters.filter(function (f) { return f.dim === dim.id; }).length;
246	      var groups = filterGroups(dim.id);
247	      var counts = {};
248	      var maxC = 1;
249	      for (var i = 0; i < RECORDS.length; i++) {
250	        var rec = RECORDS[i];
251	        if (!passFilters(rec, groups)) continue;
252	        var vi = dimIdx(rec, dim);
253	        counts[vi] = (counts[vi] || 0) + 1;
254	        if (counts[vi] > maxC) maxC = counts[vi];
255	      }
256	      var role = [];
257	      if (dim.id === projected) role.push('<span class="chip chip-proj">投影中</span>');
258	      if (dim.id === breakdown) role.push('<span class="chip chip-break">细分</span>');
259	      if (fCount) role.push('<span class="chip chip-filter">' + fCount + ' 过滤</span>');
260	
261	      html.push('<div class="dim' + (open ? ' open' : '') + '" data-dim="' + dim.id + '">');
262	      html.push('<div class="dim-hd">');
263	      html.push('<button class="dim-exp" data-k="exp:' + dim.id + '" aria-expanded="' + open + '" title="展开/收起取值">' + (open ? '▾' : '▸') + '</button>');
264	      html.push('<button class="dim-name' + (dim.id === projected ? ' is-proj' : '') + '" data-k="proj:' + dim.id + '" title="设为投影维度">' +
265	        '<span class="dim-icon" aria-hidden="true">' + dim.icon + '</span>' + dim.name +
266	        '<span class="dim-cardinality">' + dim.values.length + ' 值</span></button>');
267	      html.push('<span class="dim-role">' + role.join('') + '</span>');
268	      html.push('</div>');
269	      if (open) {
270	        html.push('<div class="dim-vals" role="group" aria-label="' + dim.name + ' 取值过滤">');
271	        dim.values.forEach(function (v, vi) {
272	          var c = counts[vi] || 0;
273	          var on = store.filters.some(function (f) { return f.dim === dim.id && f.valueIdx === vi; });
274	          html.push('<label class="dim-val' + (on ? ' on' : '') + '" title="' + v + '：' + c + ' 条（按其他维度过滤）">');
275	          html.push('<input type="checkbox" data-k="cb:' + dim.id + ':' + vi + '" data-dim="' + dim.id + '" data-vi="' + vi + '"' + (on ? ' checked' : '') + '>');
276	          html.push('<span class="dv-name">' + v + '</span>');
277	          html.push('<span class="dv-bar" aria-hidden="true"><i style="width:' + Math.round(100 * c / maxC) + '%"></i></span>');
278	          html.push('<span class="dv-count">' + c.toLocaleString('zh-CN') + '</span>');
279	          html.push('</label>');
280	        });
281	        html.push('</div>');
282	      }
283	      html.push('</div>');
284	    });
285	    $('rail-body').innerHTML = html.join('');
286	  }
287	
288	  function renderProjectionBar() {
289	    var dim = dimById[store.projection.primary];
290	    $('proj-title').textContent = '投影 · ' + dim.name;
291	    var sub = '按「' + dim.name + '」聚合当前过滤后数据';
292	    if (store.projection.breakdown) sub += '，以「' + dimById[store.projection.breakdown].name + '」细分';
293	    $('proj-sub').textContent = sub;
294	
295	    var mOpts = MEASURES.map(function (m) {
296	      return '<option value="' + m.id + '"' + (m.id === store.measure ? ' selected' : '') + '>' + m.name + '</option>';
297	    }).join('');
298	    var measureSel = $('measure-select');
299	    if (measureSel.innerHTML !== mOpts) measureSel.innerHTML = mOpts;
300	
301	    var bOpts = ['<option value="">（无细分）</option>'].concat(DIMS.filter(function (d) {
302	      return d.id !== store.projection.primary;
303	    }).map(function (d) {
304	      return '<option value="' + d.id + '"' + (d.id === store.projection.breakdown ? ' selected' : '') + '>' + d.name + '</option>';
305	    })).join('');
306	    var bSel = $('breakdown-select');
307	    if (bSel.innerHTML !== bOpts) bSel.innerHTML = bOpts;
308	  }
309	
310	  function renderChart() {
311	    var dim = dimById[store.projection.primary];
312	    var breakdown = store.projection.breakdown ? dimById[store.projection.breakdown] : null;
313	    var activeValues = {};
314	    store.filters.forEach(function (f) { if (f.dim === dim.id) activeValues[f.valueIdx] = true; });
315	
316	    var rows = dim.values.map(function (v, vi) {
317	      var recs = [];
318	      for (var i = 0; i < RECORDS.length; i++) if (dimIdx(RECORDS[i], dim) === vi) recs.push(RECORDS[i]);
319	      var agg = aggregate(recs, store.measure, dim.id);
320	      var seg = null;
321	      if (breakdown) {
322	        seg = breakdown.values.map(function (bv, bi) {
323	          var sub = recs.filter(function (r) { return dimIdx(r, breakdown) === bi && passFilters(r, filterGroups(dim.id)); });
324	          return { bi: bi, n: sub.length, value: sub.reduce(function (s, r) { return s + r[store.measure]; }, 0) };
325	        });
326	      }
327	      return { vi: vi, v: v, agg: agg, seg: seg };
328	    });
329	
330	    var max = 0;
331	    rows.forEach(function (r) { if (r.agg.value > max) max = r.agg.value; });
332	    var totalHit = rows.reduce(function (s, r) { return s + r.agg.count; }, 0);
333	
334	    var html = [];
335	    rows.forEach(function (r) {
336	      var pct = max > 0 ? Math.max(r.agg.value > 0 ? 1.5 : 0, 100 * r.agg.value / max) : 0;
337	      var pressed = !!activeValues[r.vi];
338	      var segHtml = '';
339	      if (r.seg) {
340	        var segMax = r.seg.reduce(function (s, x) { return s + x.value; }, 0) || 1;
341	        segHtml = r.seg.filter(function (x) { return x.value > 0; }).map(function (x) {
342	          return '<i class="seg" style="width:' + (100 * x.value / segMax).toFixed(2) + '%;background:' + PALETTE[x.bi % PALETTE.length] + '" title="' + dimById[store.projection.breakdown].values[x.bi] + '：' + fmtMeasure(store.measure, x.value) + '"></i>';
343	        }).join('');
344	      }
345	      html.push('<button class="bar-row' + (pressed ? ' active' : '') + (r.agg.count === 0 ? ' zero' : '') + '" data-k="bar:' + dim.id + ':' + r.vi + '" data-dim="' + dim.id + '" data-vi="' + r.vi + '" aria-pressed="' + pressed + '" title="点击' + (pressed ? '取消' : '') + '过滤：' + dim.name + '＝' + r.v + '（' + r.agg.count + ' 条）">');
346	      html.push('<span class="bar-label">' + r.v + '</span>');
347	      html.push('<span class="bar-track">' + (r.seg ? '<span class="bar bar-stack" style="width:' + pct.toFixed(2) + '%">' + segHtml + '</span>' : '<span class="bar" style="width:' + pct.toFixed(2) + '%"></span>') + '</span>');
348	      html.push('<span class="bar-value">' + fmtMeasure(store.measure, r.agg.value) + '</span>');
349	      html.push('<span class="bar-count">' + r.agg.count + ' 条</span>');
350	      html.push('</button>');
351	    });
352	    $('chart').innerHTML = html.join('');
353	    $('chart').classList.toggle('all-zero', totalHit === 0);
354	
355	    var legend = $('legend');
356	    if (breakdown) {
357	      legend.hidden = false;
358	      legend.innerHTML = '<span class="lg-title">' + breakdown.name + '：</span>' + breakdown.values.map(function (bv, bi) {
359	        return '<span class="lg-item"><i style="background:' + PALETTE[bi % PALETTE.length] + '"></i>' + bv + '</span>';
360	      }).join('');
361	    } else {
362	      legend.hidden = true;
363	      legend.innerHTML = '';
364	    }
365	  }
366	
367	  function renderTable() {
368	    var dim = dimById[store.projection.primary];
369	    var breakdown = store.projection.breakdown ? dimById[store.projection.breakdown] : null;
370	    var recs = matched().slice();
371	    var hit = recs.length;
372	    recs.sort(function (a, b) {
373	      var k = store.sort.key, d = store.sort.dir;
374	      return k === 'id' ? a.id < b.id ? -d : d : (a[k] - b[k]) * d;
375	    });
376	    var shown = recs.slice(0, TABLE_CAP);
377	
378	    var sortable = [['id', '订单号'], ['revenue', '收入'], ['units', '数量'], ['margin', '利润率']];
379	    var html = '<table><thead><tr><th class="th-dim">订单号</th>';
380	    html += '<th class="th-dim th-proj">' + dim.name + '</th>';
381	    if (breakdown) html += '<th class="th-dim">' + breakdown.name + '</th>';
382	    sortable.slice(1).forEach(function (s) {
383	      var arrow = store.sort.key === s[0] ? (store.sort.dir < 0 ? ' ↓' : ' ↑') : '';
384	      html += '<th class="th-num"><button class="th-sort" data-k="sort:' + s[0] + '" data-key="' + s[0] + '">' + s[1] + arrow + '</button></th>';
385	    });
386	    html += '</tr></thead><tbody>';
387	    shown.forEach(function (r) {
388	      var sel = r.id === store.selectedId;
389	      html += '<tr tabindex="0" data-k="row:' + r.id + '" data-rid="' + r.id + '"' + (sel ? ' class="sel"' : '') + '>';
390	      html += '<td class="td-id">' + r.id + '</td>';
391	      html += '<td class="td-dim">' + dimVal(r, dim) + '</td>';
392	      if (breakdown) html += '<td class="td-dim">' + dimVal(r, breakdown) + '</td>';
393	      html += '<td class="td-num">' + fmtMoney(r.revenue) + '</td>';
394	      html += '<td class="td-num">' + r.units + '</td>';
395	      html += '<td class="td-num">' + r.margin + '%</td>';
396	      html += '</tr>';
397	    });
398	    html += '</tbody></table>';
399	
400	    if (hit === 0) {
401	      html = '<div class="empty-state"><div class="empty-icon">◌</div>' +
402	        '<p>当前过滤条件下没有命中记录。</p>' +
403	        '<button class="btn" data-k="empty-clear" data-act="clear-filters">清空全部过滤</button></div>';
404	    }
405	    $('table-wrap').innerHTML = html;
406	    $('table-hint').textContent = hit === 0 ? '0 条命中'
407	      : '命中 ' + hit.toLocaleString('zh-CN') + ' 条 · 显示前 ' + Math.min(TABLE_CAP, hit) + ' 条（点击行查看明细）';
408	  }
409	
410	  function trayEntries() {
411	    var entries = [];
412	    entries.push({
413	      id: 'proj-primary', kind: 'projection', dim: store.projection.primary,
414	      title: '投影维度 → <b>' + dimById[store.projection.primary].name + '</b>',
415	      origin: store.projOrigin, revertHint: '回到上一投影',
416	      canRevert: store.projHistory.length > 0 || store.projection.primary !== DEFAULT_PROJECTION.primary
417	    });
418	    if (store.projection.breakdown) {
419	      entries.push({
420	        id: 'proj-breakdown', kind: 'projection', dim: store.projection.breakdown,
421	        title: '细分维度 → <b>' + dimById[store.projection.breakdown].name + '</b>',
422	        origin: store.breakdownOrigin || '未记录', revertHint: '移除细分', canRevert: true
423	      });
424	    }
425	    store.filters.forEach(function (f) {
426	      entries.push({
427	        id: f.id, kind: 'filter', dim: f.dim,
428	        title: '<b>' + dimById[f.dim].name + '</b>＝' + dimById[f.dim].values[f.valueIdx],
429	        origin: f.origin,
430	        orphan: f.dim !== store.projection.primary && f.dim !== store.projection.breakdown,
431	        revertHint: '回退该过滤', canRevert: true
432	      });
433	    });
434	    return entries;
435	  }
436	
437	  function renderTray() {
438	    var entries = trayEntries();
439	    $('tray-count').textContent = entries.length;
440	    var html = [];
441	    if (!entries.length) {
442	      html.push('<div class="tray-empty">无生效的过滤 / 投影状态。<br>所有变更都会出现在这里，并逐条可回退。</div>');
443	    }
444	    entries.forEach(function (e) {
445	      var orphanTag = e.orphan ? '<span class="tag tag-warn">不在当前投影 · 仍生效</span>' : '';
446	      html.push('<div class="state-entry kind-' + e.kind + '" data-dim="' + e.dim + '">');
447	      html.push('<span class="badge ' + (e.kind === 'filter' ? 'badge-filter' : 'badge-proj') + '">' + (e.kind === 'filter' ? '过滤' : '投影') + '</span>');
448	      html.push('<div class="entry-main"><div class="entry-title">' + e.title + '</div>' +
449	        '<div class="entry-meta"><span class="origin">来源：' + e.origin + '</span>' + orphanTag + '</div></div>');
450	      html.push('<button class="entry-x" data-k="x:' + e.id + '" data-act="' + (e.id === 'proj-primary' ? 'revert-proj' : e.id === 'proj-breakdown' ? 'clear-breakdown' : 'revert-filter') + '" data-fid="' + e.id + '" title="' + e.revertHint + '" ' + (e.canRevert ? '' : 'disabled') + '>✕</button>');
451	      html.push('</div>');
452	    });
453	    $('tray-body').innerHTML = html.join('');
454	  }
455	
456	  function renderInspector() {
457	    var body = $('inspector-body');
458	    var btn = $('btn-deselect');
459	    var rec = null;
460	    for (var i = 0; i < RECORDS.length; i++) if (RECORDS[i].id === store.selectedId) { rec = RECORDS[i]; break; }
461	    btn.hidden = !rec;
462	    if (!rec) {
463	      body.innerHTML = '<div class="insp-empty">在记录表中点击任意行，<br>这里会显示该记录的全部维度与度量。<br><span class="insp-hint">选中状态在切换投影后保持。</span></div>';
464	      return;
465	    }
466	    var inHit = passFilters(rec, filterGroups(null));
467	    var html = '';
468	    if (!inHit) {
469	      html += '<div class="insp-warn">⚠ 该记录已被当前过滤排除（选中仍保持）</div>';
470	    }
471	    html += '<div class="insp-id">' + rec.id + '</div><div class="kv-grid">';
472	    DIMS.forEach(function (dim) {
473	      var v = dimVal(rec, dim);
474	      var on = store.filters.some(function (f) { return f.dim === dim.id && f.valueIdx === dimIdx(rec, dim); });
475	      html += '<div class="kv"><span class="kv-k">' + dim.name + '</span>' +
476	        '<span class="kv-v">' + v + '</span>' +
477	        '<button class="kv-act" data-k="insp:' + dim.id + '" data-dim="' + dim.id + '" data-vi="' + dimIdx(rec, dim) + '" title="' + (on ? '取消' : '添加') + '过滤：' + dim.name + '＝' + v + '">' + (on ? '✓ 已过滤' : '过滤') + '</button></div>';
478	    });
479	    html += '<div class="kv kv-measure"><span class="kv-k">收入</span><span class="kv-v">' + fmtMoney(rec.revenue) + '</span></div>';
480	    html += '<div class="kv kv-measure"><span class="kv-k">数量</span><span class="kv-v">' + rec.units + '</span></div>';
481	    html += '<div class="kv kv-measure"><span class="kv-k">利润率</span><span class="kv-v">' + rec.margin + '%</span></div>';
482	    html += '</div>';
483	    body.innerHTML = html;
484	  }
485	
486	  /* ---------- 事件（委托，一次挂载） ---------- */
487	  $('rail-body').addEventListener('click', function (ev) {
488	    var exp = ev.target.closest('.dim-exp');
489	    if (exp) {
490	      var dim = exp.closest('.dim').getAttribute('data-dim');
491	      store.expanded[dim] = !store.expanded[dim];
492	      renderAll();
493	      return;
494	    }
495	    var name = ev.target.closest('.dim-name');
496	    if (name) {
497	      var dimId = name.closest('.dim').getAttribute('data-dim');
498	      if (dimId !== store.projection.primary) commit(makeSetProjection(dimId, '维度轨'));
499	    }
500	  });
501	  $('rail-body').addEventListener('change', function (ev) {
502	    var cb = ev.target.closest('input[type="checkbox"]');
503	    if (cb) toggleFilter(cb.getAttribute('data-dim'), +cb.getAttribute('data-vi'), '维度轨');
504	  });
505	
506	  $('chart').addEventListener('click', function (ev) {
507	    var bar = ev.target.closest('.bar-row');
508	    if (bar) toggleFilter(bar.getAttribute('data-dim'), +bar.getAttribute('data-vi'), '分布图');
509	  });
510	
511	  $('table-wrap').addEventListener('click', function (ev) {
512	    var sort = ev.target.closest('.th-sort');
513	    if (sort) {
514	      var key = sort.getAttribute('data-key');
515	      if (store.sort.key === key) store.sort.dir *= -1;
516	      else { store.sort.key = key; store.sort.dir = -1; }
517	      renderAll();
518	      return;
519	    }
520	    var clear = ev.target.closest('[data-act="clear-filters"]');
521	    if (clear) { commit(makeResetAll('空态恢复')); return; }
522	    var row = ev.target.closest('tr[data-rid]');
523	    if (row) { store.selectedId = row.getAttribute('data-rid'); renderAll(); }
524	  });
525	  $('table-wrap').addEventListener('keydown', function (ev) {
526	    if (ev.key !== 'Enter' && ev.key !== ' ') return;
527	    var row = ev.target.closest('tr[data-rid]');
528	    if (row) { ev.preventDefault(); store.selectedId = row.getAttribute('data-rid'); renderAll(); }
529	  });
530	
531	  $('tray-body').addEventListener('click', function (ev) {
532	    var x = ev.target.closest('.entry-x');
533	    if (!x) return;
534	    var act = x.getAttribute('data-act');
535	    if (act === 'revert-filter') { var op = makeRemoveFilter(x.getAttribute('data-fid')); op && commit(op); }
536	    else if (act === 'revert-proj') revertProjection();
537	    else if (act === 'clear-breakdown') commit(makeSetBreakdown(null, '托盘回退'));
538	  });
539	  /* 状态条目 hover → 高亮归属维度的轨道行（归属可视化） */
540	  $('tray-body').addEventListener('mouseover', function (ev) {
541	    var e = ev.target.closest('.state-entry');
542	    if (!e) return;
543	    var dimRow = document.querySelector('.dim[data-dim="' + e.getAttribute('data-dim') + '"]');
544	    if (dimRow) dimRow.classList.add('flash');
545	  });
546	  $('tray-body').addEventListener('mouseout', function () {
547	    document.querySelectorAll('.dim.flash').forEach(function (el) { el.classList.remove('flash'); });
548	  });
549	
550	  $('inspector-body').addEventListener('click', function (ev) {
551	    var act = ev.target.closest('.kv-act');
552	    if (act) toggleFilter(act.getAttribute('data-dim'), +act.getAttribute('data-vi'), '明细面板');
553	  });
554	  $('btn-deselect').addEventListener('click', function () { store.selectedId = null; renderAll(); });
555	
556	  $('measure-select').addEventListener('change', function (ev) { store.measure = ev.target.value; renderAll(); });
557	  $('breakdown-select').addEventListener('change', function (ev) {
558	    var v = ev.target.value || null;
559	    if (v !== store.projection.breakdown) commit(makeSetBreakdown(v, '细分下拉'));
560	  });
561	
562	  $('btn-undo').addEventListener('click', undo);
563	  $('btn-redo').addEventListener('click', redo);
564	  $('btn-reset').addEventListener('click', function () { commit(makeResetAll('头部重置')); });
565	
566	  document.addEventListener('keydown', function (ev) {
567	    if ((ev.ctrlKey || ev.metaKey) && !ev.altKey) {
568	      var k = ev.key.toLowerCase();
569	      if (k === 'z' && !ev.shiftKey) { ev.preventDefault(); undo(); return; }
570	      if (k === 'y' || (k === 'z' && ev.shiftKey)) { ev.preventDefault(); redo(); return; }
571	    }
572	    if (ev.key === 'Escape' && store.selectedId) { store.selectedId = null; renderAll(); }
573	  });
574	
575	  /* ---------- 测试钩子（验收证据用） ---------- */
576	  window.__prism = {
577	    store: store,
578	    commit: commit, undo: undo, redo: redo,
579	    toggleFilter: toggleFilter,
580	    matched: matched,
581	    trayEntries: trayEntries,
582	    makeSetProjection: makeSetProjection,
583	    makeResetAll: makeResetAll,
584	    dimById: dimById
585	  };
586	
587	  /* ---------- 初始化：数据内联，加载完成即 ready（无加载态） ---------- */
588	  try {
589	    if (!RECORDS.length || !DIMS.length) throw new Error('数据集校验失败');
590	    renderAll();
591	  } catch (err) {
592	    appEl.innerHTML = '<div class="app-error"><h2>应用初始化失败</h2><p>' + String(err && err.message || err) + '</p></div>';
593	  }
594	})();
