1	/* ============ 数据集：Nimbus SaaS 订单数据集（确定性内联生成） ============
2	 * cardinaity 语义上无界（记录可继续追加），此处内联 1,280 条确定性记录，
3	 * 页面加载即就绪 —— 不存在加载态（交付约束）。 */
4	(function (global) {
5	  'use strict';
6	
7	  /* mulberry32 —— 种子确定性 PRNG，保证每次打开数据一致 */
8	  function mulberry32(seed) {
9	    var a = seed | 0;
10	    return function () {
11	      a = (a + 0x6D2B79F5) | 0;
12	      var t = Math.imul(a ^ (a >>> 15), 1 | a);
13	      t = (t + Math.imul(t ^ (t >>> 7), 61 | t)) ^ t;
14	      return ((t ^ (t >>> 14)) >>> 0) / 4294967296;
15	    };
16	  }
17	
18	  var rnd = mulberry32(20260908);
19	
20	  function weighted(pairs) { // [[value, weight], ...]
21	    var total = 0, i;
22	    for (i = 0; i < pairs.length; i++) total += pairs[i][1];
23	    var r = rnd() * total;
24	    for (i = 0; i < pairs.length; i++) {
25	      r -= pairs[i][1];
26	      if (r <= 0) return pairs[i][0];
27	    }
28	    return pairs[pairs.length - 1][0];
29	  }
30	
31	  var CATEGORICAL = [
32	    {
33	      id: 'region', name: '区域', icon: '◍',
34	      values: ['亚太', '欧洲', '北美', '拉美', '中东非'],
35	      weights: [[0, 28], [1, 24], [2, 26], [3, 12], [4, 10]]
36	    },
37	    {
38	      id: 'category', name: '产品线', icon: '◈',
39	      values: ['分析平台', '协作套件', '安全网关', '云数据库', '开发者工具', 'AI 助手'],
40	      weights: [[0, 22], [1, 18], [2, 15], [3, 17], [4, 13], [5, 15]]
41	    },
42	    {
43	      id: 'segment', name: '客户规模', icon: '◉',
44	      values: ['初创', '中小企业', '中型市场', '大型企业'],
45	      weights: [[0, 22], [1, 34], [2, 26], [3, 18]]
46	    },
47	    {
48	      id: 'plan', name: '订阅方案', icon: '▤',
49	      values: ['Free', 'Pro', 'Business', 'Enterprise'],
50	      weights: [[0, 16], [1, 34], [2, 30], [3, 20]]
51	    },
52	    {
53	      id: 'channel', name: '渠道', icon: '⊕',
54	      values: ['直销', '渠道伙伴', '在线电商', '市场联盟'],
55	      weights: [[0, 34], [1, 26], [2, 28], [3, 12]]
56	    },
57	    {
58	      id: 'quarter', name: '季度', icon: '◫',
59	      values: ['2025Q1', '2025Q2', '2025Q3', '2025Q4', '2026Q1', '2026Q2'],
60	      weights: [[0, 12], [1, 14], [2, 16], [3, 18], [4, 19], [5, 21]]
61	    },
62	    {
63	      id: 'rep', name: '销售代表', icon: '✦',
64	      values: ['陈曦', '李昀', '王砚秋', '赵聆', '孙沐', '周子墨', '吴桐', '郑楚'],
65	      weights: [[0, 14], [1, 13], [2, 14], [3, 12], [4, 12], [5, 13], [6, 11], [7, 11]]
66	    }
67	  ];
68	
69	  /* 数值维度：订单收入 —— 以分箱参与投影/过滤，与类别维度同构 */
70	  var NUMERIC = [
71	    { id: 'revenue', name: '订单收入', icon: '◆', binCount: 8, extent: [0, 64000] }
72	  ];
73	
74	  var SEG_BASE = { '初创': 3200, '中小企业': 8600, '中型市场': 16500, '大型企业': 30500 };
